/**
 * Span naming and attribute keys for each trace format.
 *
 * `legacy` is the original `agent_sdk.*` / `cursor.*` format. `standard`
 * follows the OpenTelemetry GenAI agent span conventions. `both` keeps the
 * legacy span names and writes both attribute sets, for migrating
 * dashboards.
 */
import { createContextKey } from "@opentelemetry/api";
export const SEMCONV_ENV = "AGENT_SDK_OTEL_SEMCONV";
/** Reads `AGENT_SDK_OTEL_SEMCONV` only. Unset or empty is `legacy`. */
export function semconvFromEnv(env) {
    const raw = env[SEMCONV_ENV]?.trim().toLowerCase();
    if (raw === undefined || raw === "") {
        return { semconv: "legacy", warning: undefined };
    }
    if (raw === "legacy" || raw === "standard" || raw === "both") {
        return { semconv: raw, warning: undefined };
    }
    return {
        semconv: "legacy",
        warning: `${SEMCONV_ENV}='${env[SEMCONV_ENV]}' is not legacy, standard, or both; using legacy`,
    };
}
export function emitsLegacy(semconv) {
    return semconv !== "standard";
}
export function emitsGenAi(semconv) {
    return semconv !== "legacy";
}
const SHARED_KEYS = {
    "cursor.conversation.id": "gen_ai.conversation.id",
    "agent_sdk.session_id": "gen_ai.conversation.id",
    "agent_sdk.agent": "gen_ai.agent.name",
};
/**
 * Legacy key → GenAI key per span kind. `null` drops the key in
 * `standard`. Keys not listed keep their name in every format.
 */
const GEN_AI_KEYS = {
    turn: {
        ...SHARED_KEYS,
        "agent_sdk.usage.input_tokens": "gen_ai.usage.input_tokens",
        "agent_sdk.usage.output_tokens": "gen_ai.usage.output_tokens",
        "agent_sdk.usage.cache_read_tokens": "gen_ai.usage.cache_read.input_tokens",
        "agent_sdk.usage.cache_write_tokens": "gen_ai.usage.cache_creation.input_tokens",
        "agent_sdk.usage.reasoning_tokens": "gen_ai.usage.reasoning.output_tokens",
    },
    tool: {
        ...SHARED_KEYS,
        "cursor.tool.name": "gen_ai.tool.name",
        "cursor.tool.kind": null,
        "cursor.tool.status": null,
        "agent_sdk.call_id": "gen_ai.tool.call.id",
        "agent_sdk.tool_args": null,
        "agent_sdk.tool_output": null,
        "agent_sdk.tool_error_class": "error.type",
    },
    subagent: {
        "cursor.conversation.id": "gen_ai.conversation.id",
        "agent_sdk.session_id": "gen_ai.conversation.id",
        "agent_sdk.subagent_name": "gen_ai.agent.name",
        "agent_sdk.subagent_description": "gen_ai.agent.description",
    },
    phase: {
        "cursor.conversation.id": "gen_ai.conversation.id",
        "agent_sdk.session_id": "gen_ai.conversation.id",
    },
};
/**
 * Identity the runtime writes on its spans, in either format. An author tag
 * may not replace it in `standard` or `both`. `legacy` keeps accepting these
 * tags as it always has.
 */
const AUTHOR_IDENTITY_KEYS = new Set([
    "cursor.conversation.id",
    "agent_sdk.session_id",
    "agent_sdk.agent",
    "agent_sdk.subagent_name",
    "agent_sdk.turn_id",
    "agent_sdk.call_id",
    "cursor.tool.name",
    "gen_ai.conversation.id",
    "gen_ai.agent.name",
    "gen_ai.tool.call.id",
    "gen_ai.tool.name",
]);
/**
 * Author trace tags for one span. `legacy` returns them unchanged. `standard`
 * and `both` drop identity keys, then rename the rest like runtime keys.
 */
export function authorSpanAttributes(semconv, kind, tags) {
    if (semconv === "legacy") {
        return tags;
    }
    const kept = {};
    for (const [key, value] of Object.entries(tags)) {
        if (!AUTHOR_IDENTITY_KEYS.has(key)) {
            kept[key] = value;
        }
    }
    return semconvAttributes(semconv, kind, kept);
}
/** Which mapping a span gets, read from what the span carries at start. */
export function semconvSpanKind(name, attributes) {
    const operation = attributes["gen_ai.operation.name"];
    if (operation === "execute_tool") {
        return "tool";
    }
    if (operation === "invoke_agent") {
        return attributes["agent_sdk.call_id"] === undefined ? "turn" : "subagent";
    }
    if (name === "agent_sdk.turn") {
        return "turn";
    }
    if (name === "agent_sdk.tool") {
        return "tool";
    }
    if (name === "agent_sdk.subagent") {
        return "subagent";
    }
    return "phase";
}
const semconvKey = createContextKey("agent_sdk.semconv");
/** Carry a turn's frozen format to spans started under it. */
export function withSemconv(parent, semconv) {
    return parent.setValue(semconvKey, semconv);
}
export function semconvFrom(ctx) {
    const value = ctx.getValue(semconvKey);
    return value === "standard" || value === "both" ? value : "legacy";
}
/** Rewrite legacy-keyed attributes into the configured format. */
export function semconvAttributes(semconv, kind, legacy) {
    if (semconv === "legacy") {
        return legacy;
    }
    const keys = GEN_AI_KEYS[kind];
    const out = {};
    for (const [key, value] of Object.entries(legacy)) {
        const mapped = keys[key];
        if (mapped === undefined || semconv === "both") {
            out[key] = value;
        }
        if (typeof mapped === "string") {
            out[mapped] = value;
        }
    }
    return out;
}
/** GenAI keys that no legacy key maps to, set once at span start. */
export function genAiStartAttributes(semconv, kind) {
    if (!emitsGenAi(semconv)) {
        return {};
    }
    switch (kind) {
        case "turn":
        case "subagent":
            return { "gen_ai.operation.name": "invoke_agent" };
        case "tool":
            return { "gen_ai.operation.name": "execute_tool" };
        case "phase":
            return {};
        default: {
            const exhaustive = kind;
            return exhaustive;
        }
    }
}
export function turnSpanName(semconv, agentName) {
    return semconv === "standard" ? `invoke_agent ${agentName}` : "agent_sdk.turn";
}
export function toolSpanName(semconv, toolName) {
    return semconv === "standard" ? `execute_tool ${toolName}` : "agent_sdk.tool";
}
export function subagentSpanName(semconv, name) {
    if (semconv !== "standard") {
        return "agent_sdk.subagent";
    }
    return name === undefined || name === "" ? "invoke_agent" : `invoke_agent ${name}`;
}
/** Conversation id keys copied onto spans the author starts during a turn. */
export function conversationIdKeys(semconv) {
    switch (semconv) {
        case "legacy":
            return ["cursor.conversation.id"];
        case "standard":
            return ["gen_ai.conversation.id"];
        case "both":
            return ["cursor.conversation.id", "gen_ai.conversation.id"];
        default: {
            const exhaustive = semconv;
            return exhaustive;
        }
    }
}
